{
  "name": "@pplante/opencode-worktrunk",
  "version": "0.3.2",
  "description": "OpenCode plugin for Worktrunk worktree management",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode worktree plugin",
    "opencode worktrunk",
    "opencode ai",
    "slash-command",
    "coding-agent",
    "ai-agent",
    "developer-tools",
    "agent",
    "tui"
  ],
  "type": "module",
  "exports": {
    "./server": {
      "import": "./dist/server.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "clean": "rm -rf dist",
    "build": "bun run clean && bun build ./src/worktrunk-wt.ts ./src/server.ts --outdir ./dist --target bun --external @opencode-ai/plugin --external @opencode/plugin",
    "lint": "oxlint src/",
    "pack:dry-run": "npm pack --dry-run",
    "test": "bun test",
    "test:coverage": "bun test --coverage",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "bun run test && bun run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.15.13"
  },
  "devDependencies": {
    "@types/bun": "^1.3.13",
    "typescript": "^7.0.2"
  },
  "engines": {
    "opencode": ">=1.17.1"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.3"
  }
}
